<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids; use Illuminate\Database\Eloquent\Model;
class Lead extends Model { use HasUuids; protected $fillable=['tenant_id','company_id','branch_id','customer_id','owner_id','name','contact_name','email','phone','company','lead_source','priority','state','estimated_value','estimated_budget','currency','interested_product','expected_contact_at','description','notes']; protected function casts():array{return ['estimated_value'=>'decimal:6','estimated_budget'=>'decimal:6','expected_contact_at'=>'datetime'];} public function customer(){return $this->belongsTo(Customer::class);} public function owner(){return $this->belongsTo(User::class,'owner_id');} public function company(){return $this->belongsTo(Company::class);} public function branch(){return $this->belongsTo(Branch::class);} public function activities(){return $this->hasMany(CrmActivity::class);} public function conversion(){return $this->hasOne(CrmLeadConversion::class);} }
